<?php
require_once '_bootstrap.php'; require_admin_permission('catalog.manage'); $db=admin_db();
if($_SERVER['REQUEST_METHOD']==='POST' && isset($_POST['package_action'])){
    verify_csrf(); $id=(int)($_POST['id']??0); $action=$_POST['package_action'];
    if(!in_array($action,['archive','publish','delete'],true))redirect_with_message('packages.php','Invalid package action.');
    if($action==='delete'){$s=$db->prepare('SELECT COUNT(*) total FROM bookings WHERE package_id=?');$s->bind_param('i',$id);$s->execute();$used=(int)$s->get_result()->fetch_assoc()['total'];if($used)redirect_with_message('packages.php','This package has bookings. Archive it to preserve booking history.');$s=$db->prepare('SELECT image FROM packages WHERE id=?');$s->bind_param('i',$id);$s->execute();$oldImage=$s->get_result()->fetch_assoc()['image']??null;$s=$db->prepare('DELETE FROM packages WHERE id=?');$s->bind_param('i',$id);$s->execute();admin_remove_unused_image($db,$oldImage);}
    else{$status=$action==='publish'?'published':'archived';$s=$db->prepare('UPDATE packages SET status=? WHERE id=?');$s->bind_param('si',$status,$id);$s->execute();}
    admin_audit($db,$action,'package',(string)$id);redirect_with_message('packages.php','Package action completed.');
}
if($_SERVER['REQUEST_METHOD']==='POST'){
    verify_csrf(); $id=(int)($_POST['id']??0); $stateId=(int)($_POST['state_id']??0);$transportId=(int)($_POST['transport_category_id']??0); $name=trim($_POST['name']??''); $destination=trim($_POST['destination']??''); $description=trim($_POST['description']??'');$places=[];foreach(explode(',',(string)($_POST['visit_places']??'')) as $place){$place=trim($place);$keys=array_map('strtolower',$places);if($place!==''&&!in_array(strtolower($place),$keys,true))$places[]=$place;}$visitPlaces=implode(', ',$places); $price=(float)($_POST['price']??0); $days=(int)($_POST['duration_days']??0); $rating=(int)($_POST['hotel_rating']??0); $status=$_POST['status']??'draft';
    $oldImage=null;if($id){$s=$db->prepare('SELECT image FROM packages WHERE id=?');$s->bind_param('i',$id);$s->execute();$oldImage=$s->get_result()->fetch_assoc()['image']??null;}$image=admin_upload_image('package_image','packages')?:$oldImage;
    $transport='';if($transportId){$s=$db->prepare("SELECT name FROM transport_categories WHERE id=? AND status='active'");$s->bind_param('i',$transportId);$s->execute();$transport=$s->get_result()->fetch_assoc()['name']??'';}
    $slug=strtolower(trim(preg_replace('/[^a-z0-9]+/i','-',$name),'-')).($id?'':'-'.substr(bin2hex(random_bytes(2)),0,4));
    if(count($places)<5||count($places)>7)redirect_with_message('packages.php'.($id?'?edit='.$id:''),'Enter 5 to 7 unique places to visit, separated by commas.');
    if(!$stateId||!$transportId||$transport===''||$name===''||$destination===''||$description===''||!$image||$price<=0||$days<1||!in_array($status,['draft','published','archived'],true))redirect_with_message('packages.php','Select a region and transport category, upload an image, and complete every required field.');
    if($id){$s=$db->prepare("UPDATE packages SET state_id=?,transport_category_id=?,name=?,destination=?,description=?,visit_places=?,image=?,price=?,currency='INR',duration_days=?,hotel_rating=?,transport=?,status=? WHERE id=?");$s->bind_param('iisssssdiissi',$stateId,$transportId,$name,$destination,$description,$visitPlaces,$image,$price,$days,$rating,$transport,$status,$id);$s->execute();admin_remove_unused_image($db,$oldImage);admin_audit($db,'update','package',(string)$id,$name);}
    else{$s=$db->prepare("INSERT INTO packages(state_id,transport_category_id,name,slug,destination,description,visit_places,image,price,currency,duration_days,hotel_rating,transport,status) VALUES(?,?,?,?,?,?,?,?,?,'INR',?,?,?,?)");$s->bind_param('iissssssdiiss',$stateId,$transportId,$name,$slug,$destination,$description,$visitPlaces,$image,$price,$days,$rating,$transport,$status);$s->execute();$id=$db->insert_id;admin_audit($db,'create','package',(string)$id,$name);}
    redirect_with_message('packages.php','Indian tour package saved successfully.');
}
$states=[];$r=$db->query("SELECT id,name,type FROM states WHERE status='active' ORDER BY name");while($row=$r->fetch_assoc())$states[]=$row;
$transports=[];$r=$db->query("SELECT id,name FROM transport_categories WHERE status='active' ORDER BY name");while($row=$r->fetch_assoc())$transports[]=$row;
$edit=null;$editOffers=[];if(!empty($_GET['edit'])){$id=(int)$_GET['edit'];$s=$db->prepare('SELECT * FROM packages WHERE id=?');$s->bind_param('i',$id);$s->execute();$edit=$s->get_result()->fetch_assoc();$r=$db->execute_query("SELECT o.id,o.name,o.booking_end_at FROM offers o JOIN offer_packages op ON op.offer_id=o.id WHERE op.package_id=? AND o.status='active' AND NOW() BETWEEN o.booking_start_at AND o.booking_end_at ORDER BY o.priority DESC",[$id]);while($row=$r->fetch_assoc())$editOffers[]=$row;}
$showForm=isset($_GET['action'])||$edit;$search=admin_search();$condition=admin_search_condition($db,['p.name','p.destination','s.name','p.status'],$search);$where=$condition?' WHERE '.$condition:'';$pagination=admin_paginate($db,'SELECT COUNT(*) total FROM packages p LEFT JOIN states s ON s.id=p.state_id'.$where);$packages=$db->query('SELECT p.*,s.name state_name,(SELECT COUNT(*) FROM offer_packages op JOIN offers o ON o.id=op.offer_id WHERE op.package_id=p.id AND o.status=\'active\' AND NOW() BETWEEN o.booking_start_at AND o.booking_end_at) active_offer_count,(SELECT AVG(package_rating) FROM booking_reviews r WHERE r.package_id=p.id AND r.status=\'published\') avg_rating,(SELECT COUNT(*) FROM booking_reviews r WHERE r.package_id=p.id AND r.status=\'published\') review_count FROM packages p LEFT JOIN states s ON s.id=p.state_id'.$where.' ORDER BY p.updated_at DESC LIMIT '.$pagination['limit'].' OFFSET '.$pagination['offset']);$pageTitle='Packages';include '_header.php';
?>
<div class="page-head"><div><span>India tourism catalog</span><h1>Packages</h1></div><a class="primary-btn" href="packages.php?action=new"><i class="fa-solid fa-plus"></i>New package</a></div>
<?php if($showForm):?><section class="panel form-panel"><div class="panel-head"><h2><?php echo $edit?'Edit package':'Create package';?></h2><a href="packages.php">Close</a></div><form class="admin-form" method="post" enctype="multipart/form-data"><?php echo csrf_input();?><input type="hidden" name="id" value="<?php echo (int)($edit['id']??0);?>">
<label>State / Union Territory<select name="state_id" required><option value="">Select region</option><?php foreach($states as $state):?><option value="<?php echo (int)$state['id'];?>" <?php echo (int)($edit['state_id']??0)===(int)$state['id']?'selected':'';?>><?php echo e($state['name']);?><?php echo $state['type']==='union_territory'?' (UT)':'';?></option><?php endforeach;?></select></label>
<label>Package name<input name="name" value="<?php echo e($edit['name']??'');?>" required></label><label>Destination / City<input name="destination" value="<?php echo e($edit['destination']??'');?>" required></label><label class="wide">Description<textarea name="description" required><?php echo e($edit['description']??'');?></textarea></label><label class="wide upload-field">Package image <small><?php echo $edit?'Choose a file only to replace the current image.':'JPG, PNG, or WebP up to 5 MB.';?></small><?php if($edit&&!empty($edit['image'])):?><img class="upload-preview" src="../<?php echo e($edit['image']);?>" alt="Current package image"><?php endif;?><input type="file" name="package_image" accept="image/jpeg,image/png,image/webp" <?php echo $edit?'':'required';?>></label><label>Price per traveller (INR)<input type="number" step="1" min="1" name="price" value="<?php echo e($edit['price']??'');?>" required></label><label>Duration days<input type="number" min="1" name="duration_days" value="<?php echo e($edit['duration_days']??3);?>" required></label><label>Hotel rating<input type="number" min="1" max="5" name="hotel_rating" value="<?php echo e($edit['hotel_rating']??3);?>" required></label><label>Transport category<select name="transport_category_id" required><option value="">Select transport</option><?php foreach($transports as $transport):?><option value="<?php echo (int)$transport['id'];?>" <?php echo (int)($edit['transport_category_id']??0)===(int)$transport['id']?'selected':'';?>><?php echo e($transport['name']);?></option><?php endforeach;?></select></label><label>Status<select name="status"><?php foreach(['draft','published','archived'] as $v):?><option <?php echo ($edit['status']??'draft')===$v?'selected':'';?>><?php echo ucfirst($v);?></option><?php endforeach;?></select></label><div class="form-actions"><button>Save package</button></div></form><?php if($edit):?><div class="panel-head"><div><h2>Active offers</h2><div class="offer-summary"><?php foreach($editOffers as $offer):?><a class="pill" href="offers.php?edit=<?php echo (int)$offer['id'];?>"><?php echo e($offer['name']);?> · expires <?php echo e(date('d M Y',strtotime($offer['booking_end_at'])));?></a><?php endforeach;?><?php if(!$editOffers):?><span>No active offers</span><?php endif;?></div></div><a class="primary-btn" href="offers.php?action=new&package_id=<?php echo (int)$edit['id'];?>"><i class="fa-solid fa-tag"></i>Assign offer</a></div><?php endif;?></section><?php endif;?>
<section class="panel"><div class="table-wrap"><table><thead><tr><th>Package</th><th>State / UT</th><th>Destination</th><th>Price</th><th>Rating</th><th>Offers</th><th>Duration</th><th>Status</th><th>Actions</th></tr></thead><tbody><?php while($p=$packages->fetch_assoc()):?><tr><td><div class="table-title"><img src="../<?php echo e($p['image']);?>" alt=""><strong><?php echo e($p['name']);?></strong></div></td><td><?php echo e($p['state_name']?:'Not assigned');?></td><td><?php echo e($p['destination']);?></td><td><?php echo inr($p['price']);?></td><td><?php echo (int)$p['review_count']?number_format((float)$p['avg_rating'],1).'/5':'No reviews';?><small><?php echo (int)$p['review_count'];?> review(s)</small></td><td><div class="offer-summary"><?php if($p['active_offer_count']):?><span class="pill"><?php echo (int)$p['active_offer_count'];?> active</span><?php else:?><small>None</small><?php endif;?><a class="icon-btn" href="offers.php?action=new&package_id=<?php echo (int)$p['id'];?>" title="Assign offer"><i class="fa-solid fa-tag"></i></a></div></td><td><?php echo (int)$p['duration_days'];?> days</td><td><span class="pill"><?php echo e($p['status']);?></span></td><td><div class="action-row"><a class="icon-btn" href="packages.php?edit=<?php echo (int)$p['id'];?>" title="Edit"><i class="fa-solid fa-pen"></i></a><form method="post"><?php echo csrf_input();?><input type="hidden" name="id" value="<?php echo (int)$p['id'];?>"><input type="hidden" name="package_action" value="<?php echo $p['status']==='published'?'archive':'publish';?>"><button class="icon-btn" title="<?php echo $p['status']==='published'?'Disable':'Publish';?>"><i class="fa-solid <?php echo $p['status']==='published'?'fa-ban':'fa-eye';?>"></i></button></form><form method="post" onsubmit="return confirm('Permanently delete this package?')"><?php echo csrf_input();?><input type="hidden" name="id" value="<?php echo (int)$p['id'];?>"><input type="hidden" name="package_action" value="delete"><button class="icon-btn danger-icon" title="Delete"><i class="fa-solid fa-trash"></i></button></form></div></td></tr><?php endwhile;?></tbody></table></div><?php admin_pagination($pagination);?></section><?php include '_footer.php';?>
